mapper.select:
SELECT o.id, o.plate_no AS plateNo, o.space_id AS spaceId, p.location AS spaceName, o.identify_time AS identifyTime, o.occupy_type AS occupyType, o.status, o.station_id AS stationId, s.name AS stationName, o.handle_user_id AS handleUserId, u.nickname AS handleUserName, o.handle_time AS handleTime, o.handle_method AS handleMethod, o.ignore_reason AS ignoreReason, o.remark, o.reserve1, o.reserve2, o.creator, o.updater, o.create_time AS createTime, o.update_time AS updateTime FROM oil_car_handle o LEFT JOIN station_info s ON o.station_id = s.id AND s.deleted = 0 LEFT JOIN user_info u ON o.handle_user_id = u.id AND u.deleted = 0 LEFT JOIN parking_space_info p ON o.space_id = p.id AND p.deleted = 0 WHERE o.deleted = 0
AND o.plate_no LIKE CONCAT('%', #{reqVO.plateNo}, '%')
AND o.space_id = #{reqVO.spaceId}
AND o.identify_time BETWEEN #{reqVO.identifyTime[0]} AND #{reqVO.identifyTime[1]}
AND o.occupy_type = #{reqVO.occupyType}
AND o.status = #{reqVO.status}
AND o.station_id = #{reqVO.stationId}
AND o.handle_user_id = #{reqVO.handleUserId}
AND o.remark LIKE CONCAT('%', #{reqVO.remark}, '%')
ORDER BY o.id DESC
